insert into licoes (nivel, ordem, titulo, sub, icon, explicacao, dica, exemplos, questoes) values
('C2', 5001, $$Idioms com comida$$, $$piece of cake$$, $$🍰$$, $$A comida rende idioms deliciosos: piece of cake (moleza), spill the beans (dar com a língua nos dentes), butter someone up (bajular), in a nutshell (em resumo), bring home the bacon (sustentar a casa).$$, $$"Piece of cake" não é sobremesa: é algo muito fácil.$$, $j$[{"en": "The test was a piece of cake.", "pt": "A prova foi moleza."}, {"en": "Who spilled the beans about the party?", "pt": "Quem entregou o segredo da festa?"}, {"en": "In a nutshell, we need more time.", "pt": "Em resumo, precisamos de mais tempo."}]$j$::jsonb, $j$[{"q": "'Piece of cake' =", "ctx": "", "opts": ["muito fácil", "sobremesa", "pedaço pequeno", "receita"], "ans": 0, "exp": "Moleza."}, {"q": "'Spill the beans' =", "ctx": "", "opts": ["revelar um segredo", "derrubar comida", "cozinhar mal", "fazer bagunça"], "ans": 0, "exp": "Entregar o segredo."}, {"q": "'Butter someone up' =", "ctx": "", "opts": ["bajular", "engordar", "cozinhar para alguém", "irritar"], "ans": 0, "exp": "Elogiar por interesse."}, {"q": "'In a nutshell' =", "ctx": "", "opts": ["em resumo", "dentro da casca", "em segredo", "com detalhes"], "ans": 0, "exp": "Resumidamente."}, {"q": "'Bring home the bacon' =", "ctx": "", "opts": ["sustentar a casa", "fazer compras", "cozinhar bacon", "chegar cedo"], "ans": 0, "exp": "Ganhar o pão."}, {"q": "A melhor tradução de 'moleza' é:", "ctx": "", "opts": ["a piece of cake", "a slice of bread", "a cup of tea only", "a bowl of soup"], "ans": 0, "exp": "Idiom clássico."}]$j$::jsonb),
('C2', 5002, $$Idioms com cores$$, $$out of the blue$$, $$🎨$$, $$Cores pintam a fala nativa: out of the blue (do nada), once in a blue moon (raramente), green with envy (morrendo de inveja), red tape (burocracia), white lie (mentirinha inofensiva).$$, $$"Out of the blue" vem do céu azul: algo que cai do nada, sem aviso.$$, $j$[{"en": "He called me out of the blue.", "pt": "Ele me ligou do nada."}, {"en": "We eat out once in a blue moon.", "pt": "Comemos fora raramente."}, {"en": "It was just a white lie.", "pt": "Foi só uma mentirinha."}]$j$::jsonb, $j$[{"q": "'Out of the blue' =", "ctx": "", "opts": ["de repente, sem aviso", "do fundo do mar", "de tristeza", "com calma"], "ans": 0, "exp": "Do nada."}, {"q": "'Once in a blue moon' =", "ctx": "", "opts": ["muito raramente", "toda lua cheia", "uma vez por mês", "sempre à noite"], "ans": 0, "exp": "Quase nunca."}, {"q": "'Green with envy' =", "ctx": "", "opts": ["morto de inveja", "passando mal", "sem experiência", "ecológico"], "ans": 0, "exp": "Inveja intensa."}, {"q": "'Red tape' =", "ctx": "", "opts": ["burocracia", "fita adesiva", "perigo", "multa"], "ans": 0, "exp": "Excesso de burocracia."}, {"q": "'White lie' =", "ctx": "", "opts": ["mentira inofensiva", "mentira grave", "verdade dura", "segredo"], "ans": 0, "exp": "Mentirinha social."}, {"q": "'Caught red-handed' =", "ctx": "", "opts": ["pego no flagra", "com frio", "machucado", "envergonhado"], "ans": 0, "exp": "Flagrante."}]$j$::jsonb),
('C2', 5003, $$Idioms com números$$, $$back to square one$$, $$🔢$$, $$Números além da matemática: back to square one (voltar à estaca zero), on cloud nine (nas nuvens), two-faced (falso), at sixes and sevens (confuso), a one-track mind (só pensa numa coisa).$$, $$"On cloud nine" = felicidade máxima — a nuvem nove era a mais alta na escala antiga.$$, $j$[{"en": "The deal failed, so we're back to square one.", "pt": "O acordo falhou, voltamos à estaca zero."}, {"en": "She's been on cloud nine since the news.", "pt": "Ela está nas nuvens desde a notícia."}, {"en": "Don't trust him — he's two-faced.", "pt": "Não confie nele — ele é falso."}]$j$::jsonb, $j$[{"q": "'Back to square one' =", "ctx": "", "opts": ["voltar à estaca zero", "voltar para casa", "ganhar o jogo", "ficar em 1º"], "ans": 0, "exp": "Recomeçar do zero."}, {"q": "'On cloud nine' =", "ctx": "", "opts": ["muito feliz", "no avião", "distraído", "com medo"], "ans": 0, "exp": "Nas nuvens."}, {"q": "'Two-faced' =", "ctx": "", "opts": ["falso, hipócrita", "gêmeo", "indeciso", "duas vezes melhor"], "ans": 0, "exp": "Tem duas caras."}, {"q": "'At sixes and sevens' =", "ctx": "", "opts": ["confuso, desorganizado", "jogando dados", "bem arrumado", "atrasado"], "ans": 0, "exp": "Bagunça e confusão."}, {"q": "'It takes two to tango' =", "ctx": "", "opts": ["a culpa é dos dois", "dançar é bom", "é preciso treinar", "vá dançar"], "ans": 0, "exp": "Os dois lados participam."}, {"q": "'The eleventh hour' =", "ctx": "", "opts": ["o último momento", "onze da manhã", "hora do almoço", "hora extra"], "ans": 0, "exp": "Em cima da hora."}]$j$::jsonb),
('C2', 5004, $$Idioms do mar$$, $$in the same boat$$, $$⛵$$, $$A tradição naval marcou o inglês: in the same boat (no mesmo barco), learn the ropes (pegar o jeito), miss the boat (perder a chance), plain sailing (tranquilo), weather the storm (aguentar a crise).$$, $$"Learn the ropes" vem dos marinheiros aprendendo as cordas do navio.$$, $j$[{"en": "We're all in the same boat here.", "pt": "Estamos todos no mesmo barco."}, {"en": "It took a week to learn the ropes.", "pt": "Levou uma semana para pegar o jeito."}, {"en": "After the update, it was plain sailing.", "pt": "Depois da atualização, foi tranquilo."}]$j$::jsonb, $j$[{"q": "'Learn the ropes' =", "ctx": "", "opts": ["pegar o jeito", "estudar nós", "velejar", "escalar"], "ans": 0, "exp": "Aprender o básico do trabalho."}, {"q": "'Miss the boat' =", "ctx": "", "opts": ["perder a oportunidade", "perder o navio", "sentir saudade", "chegar cedo"], "ans": 0, "exp": "A chance passou."}, {"q": "'Plain sailing' =", "ctx": "", "opts": ["fácil, sem problemas", "mar agitado", "viagem longa", "voo direto"], "ans": 0, "exp": "Tudo tranquilo."}, {"q": "'Weather the storm' =", "ctx": "", "opts": ["superar a crise", "prever chuva", "sair no temporal", "reclamar do tempo"], "ans": 0, "exp": "Aguentar tempos difíceis."}, {"q": "'Show someone the ropes' =", "ctx": "", "opts": ["ensinar o básico", "amarrar", "ameaçar", "demitir"], "ans": 0, "exp": "Treinar um novato."}, {"q": "'In the same boat' =", "ctx": "", "opts": ["na mesma situação", "no mesmo time", "na mesma casa", "viajando juntos"], "ans": 0, "exp": "Mesma dificuldade."}]$j$::jsonb),
('C2', 5005, $$Idioms de esporte$$, $$the ball is in your court$$, $$🏆$$, $$O esporte invadiu o escritório: the ball is in your court (a decisão é sua), move the goalposts (mudar as regras no meio do jogo), throw in the towel (jogar a toalha), ballpark figure (número aproximado), level playing field (condições iguais).$$, $$"Ballpark figure" vem do beisebol: uma estimativa 'dentro do estádio'.$$, $j$[{"en": "I sent the proposal — the ball is in your court.", "pt": "Enviei a proposta — a decisão é sua."}, {"en": "They keep moving the goalposts.", "pt": "Eles vivem mudando as regras."}, {"en": "Give me a ballpark figure.", "pt": "Me dá um número aproximado."}]$j$::jsonb, $j$[{"q": "'The ball is in your court' =", "ctx": "", "opts": ["é a sua vez de decidir", "você ganhou", "a bola é sua", "vá jogar"], "ans": 0, "exp": "A próxima jogada é sua."}, {"q": "'Move the goalposts' =", "ctx": "", "opts": ["mudar as regras no meio", "trocar de estádio", "marcar gol", "treinar mais"], "ans": 0, "exp": "Critérios que mudam."}, {"q": "'Throw in the towel' =", "ctx": "", "opts": ["desistir", "tomar banho", "brigar", "provocar"], "ans": 0, "exp": "Jogar a toalha."}, {"q": "'Ballpark figure' =", "ctx": "", "opts": ["estimativa aproximada", "número exato", "preço alto", "estatística"], "ans": 0, "exp": "Valor por alto."}, {"q": "'Level playing field' =", "ctx": "", "opts": ["condições iguais para todos", "campo plano", "jogo empatado", "gramado novo"], "ans": 0, "exp": "Disputa justa."}, {"q": "'Get the ball rolling' =", "ctx": "", "opts": ["dar o pontapé inicial", "rolar no chão", "encerrar", "adiar"], "ans": 0, "exp": "Começar algo."}]$j$::jsonb),
('C2', 5006, $$Idioms de guerra$$, $$bite the bullet$$, $$🎖️$$, $$Idioms nascidos nos campos de batalha: bite the bullet (encarar o inevitável), stick to your guns (manter sua posição), drop a bombshell (soltar uma bomba), up in arms (revoltado), fight a losing battle (lutar por causa perdida).$$, $$"Bite the bullet": soldados mordiam a bala na cirurgia sem anestesia.$$, $j$[{"en": "I bit the bullet and told the truth.", "pt": "Encarei e contei a verdade."}, {"en": "She stuck to her guns in the meeting.", "pt": "Ela manteve a posição na reunião."}, {"en": "He dropped a bombshell: he's leaving.", "pt": "Ele soltou uma bomba: vai embora."}]$j$::jsonb, $j$[{"q": "'Bite the bullet' =", "ctx": "", "opts": ["encarar algo difícil", "comer rápido", "atirar", "ficar em silêncio"], "ans": 0, "exp": "Enfrentar o inevitável."}, {"q": "'Stick to your guns' =", "ctx": "", "opts": ["manter sua posição", "andar armado", "atirar primeiro", "colar algo"], "ans": 0, "exp": "Não ceder."}, {"q": "'Drop a bombshell' =", "ctx": "", "opts": ["dar notícia chocante", "explodir algo", "desistir", "gritar"], "ans": 0, "exp": "Notícia-bomba."}, {"q": "'Up in arms' =", "ctx": "", "opts": ["revoltado", "de braços erguidos", "rendido", "animado"], "ans": 0, "exp": "Em pé de guerra."}, {"q": "'Fight a losing battle' =", "ctx": "", "opts": ["insistir em causa perdida", "perder de propósito", "treinar luta", "fugir da briga"], "ans": 0, "exp": "Não tem como vencer."}, {"q": "'Keep your head down' =", "ctx": "", "opts": ["evitar chamar atenção", "dormir", "concordar", "rezar"], "ans": 0, "exp": "Ficar na sua."}]$j$::jsonb),
('C2', 5007, $$Expressões de tempo$$, $$in the nick of time$$, $$⏰$$, $$Tempo é idiom: in the nick of time (em cima da hora), around the clock (24 horas por dia), call it a day (encerrar por hoje), against the clock (contra o relógio), time flies (o tempo voa).$$, $$"Call it a day" = decidir que o trabalho de hoje acabou.$$, $j$[{"en": "The doctor arrived in the nick of time.", "pt": "O médico chegou bem em cima da hora."}, {"en": "They worked around the clock.", "pt": "Trabalharam sem parar, dia e noite."}, {"en": "It's late — let's call it a day.", "pt": "Está tarde — vamos encerrar por hoje."}]$j$::jsonb, $j$[{"q": "'In the nick of time' =", "ctx": "", "opts": ["no último segundo", "com folga", "atrasado", "sem pressa"], "ans": 0, "exp": "Em cima da hora."}, {"q": "'Around the clock' =", "ctx": "", "opts": ["sem parar, 24h", "perto do relógio", "uma vez por dia", "em círculos"], "ans": 0, "exp": "Dia e noite."}, {"q": "'Call it a day' =", "ctx": "", "opts": ["encerrar por hoje", "marcar um dia", "dar nome ao dia", "acordar"], "ans": 0, "exp": "Chega por hoje."}, {"q": "'Against the clock' =", "ctx": "", "opts": ["correndo contra o tempo", "sem relógio", "fora de hora", "devagar"], "ans": 0, "exp": "Prazo apertado."}, {"q": "'Time flies' =", "ctx": "", "opts": ["o tempo passa rápido", "hora do voo", "o tempo para", "que tédio"], "ans": 0, "exp": "Voa!"}, {"q": "'For the time being' =", "ctx": "", "opts": ["por enquanto", "para sempre", "no passado", "às vezes"], "ans": 0, "exp": "Temporariamente."}]$j$::jsonb),
('C2', 5008, $$GET em nível expert$$, $$get away with$$, $$🧲$$, $$GET é o canivete suíço do inglês: get away with (sair impune), get around to (finalmente fazer), get by (se virar), get over (superar), get carried away (empolgar-se demais).$$, $$"I never got around to it" = eu nunca arrumei tempo para fazer.$$, $j$[{"en": "He cheated and got away with it.", "pt": "Ele trapaceou e saiu impune."}, {"en": "I finally got around to replying.", "pt": "Finalmente arrumei tempo para responder."}, {"en": "She gets by on a small salary.", "pt": "Ela se vira com um salário pequeno."}]$j$::jsonb, $j$[{"q": "'Get away with' =", "ctx": "", "opts": ["sair impune", "fugir de casa", "viajar", "esconder"], "ans": 0, "exp": "Fazer algo errado sem punição."}, {"q": "'Get around to' =", "ctx": "", "opts": ["finalmente fazer algo adiado", "dar a volta", "contornar", "evitar"], "ans": 0, "exp": "Arrumar tempo para."}, {"q": "'Get by' =", "ctx": "", "opts": ["se virar", "passar por cima", "comprar", "desmaiar"], "ans": 0, "exp": "Sobreviver com o que tem."}, {"q": "'Get over' =", "ctx": "", "opts": ["superar", "pular", "terminar", "começar"], "ans": 0, "exp": "Superar (doença, término)."}, {"q": "'Get carried away' =", "ctx": "", "opts": ["empolgar-se demais", "ser carregado", "mudar-se", "cansar"], "ans": 0, "exp": "Perder a medida."}, {"q": "'Get out of (doing something)' =", "ctx": "", "opts": ["escapar de uma obrigação", "sair do carro", "entender", "desistir do emprego"], "ans": 0, "exp": "Livrar-se de algo chato."}]$j$::jsonb),
('C2', 5009, $$Verbos delexicais$$, $$have a go$$, $$🎲$$, $$Nativos dizem have/take/make/give/do + substantivo: have a go (tentar), take a nap (tirar uma soneca), make an effort (esforçar-se), give it a try (experimentar), do the dishes (lavar a louça). O verbo quase não tem significado — o substantivo manda.$$, $$Errado: "make a nap". Certo: "take a nap". Colocação é memorização!$$, $j$[{"en": "Why don't you have a go?", "pt": "Por que você não tenta?"}, {"en": "I'll take a quick nap after lunch.", "pt": "Vou tirar uma soneca rápida depois do almoço."}, {"en": "She made a huge effort to be here.", "pt": "Ela fez um esforço enorme para estar aqui."}]$j$::jsonb, $j$[{"q": "Tirar uma soneca:", "ctx": "", "opts": ["take a nap", "make a nap", "do a nap", "have a sleep on"], "ans": 0, "exp": "Take a nap."}, {"q": "Tentar (informal, BrE):", "ctx": "", "opts": ["have a go", "make a go", "do a try", "take a tempt"], "ans": 0, "exp": "Have a go / give it a try."}, {"q": "Fazer um esforço:", "ctx": "", "opts": ["make an effort", "do an effort", "take an effort", "have an effort"], "ans": 0, "exp": "Make an effort."}, {"q": "Lavar a louça:", "ctx": "", "opts": ["do the dishes", "make the dishes", "clean dishes up all", "have the dishes"], "ans": 0, "exp": "Do the dishes."}, {"q": "Dar uma olhada:", "ctx": "", "opts": ["take a look", "make a look", "do a look", "put a look"], "ans": 0, "exp": "Take/have a look."}, {"q": "Tomar uma decisão:", "ctx": "", "opts": ["make a decision", "do a decision", "take a decision always", "have a decide"], "ans": 0, "exp": "Make a decision."}]$j$::jsonb),
('C2', 5010, $$Sinônimos de SAD$$, $$devastated$$, $$🌧️$$, $$Chega de só 'sad': down (na fossa), gloomy (melancólico), miserable (infeliz), heartbroken (de coração partido), devastated (arrasado). Cada um tem uma intensidade.$$, $$Escala: down < gloomy < miserable < heartbroken < devastated.$$, $j$[{"en": "She was devastated by the news.", "pt": "Ela ficou arrasada com a notícia."}, {"en": "He's been feeling down lately.", "pt": "Ele anda meio na fossa ultimamente."}, {"en": "It was a gloomy, rainy Sunday.", "pt": "Era um domingo melancólico e chuvoso."}]$j$::jsonb, $j$[{"q": "O MAIS forte:", "ctx": "", "opts": ["devastated", "down", "gloomy", "sad"], "ans": 0, "exp": "Arrasado."}, {"q": "'Na fossa', leve e informal:", "ctx": "", "opts": ["down", "devastated", "grieving", "furious"], "ans": 0, "exp": "Feeling down."}, {"q": "Coração partido:", "ctx": "", "opts": ["heartbroken", "handmade", "heartburn", "headstrong"], "ans": 0, "exp": "Heartbroken."}, {"q": "Dia cinzento e triste:", "ctx": "", "opts": ["gloomy", "shiny", "crispy", "spicy"], "ans": 0, "exp": "Gloomy."}, {"q": "'Miserable' =", "ctx": "", "opts": ["muito infeliz", "miserável financeiramente", "avarento", "doente"], "ans": 0, "exp": "Infelicidade profunda."}, {"q": "'I'm gutted' (BrE, informal) =", "ctx": "", "opts": ["estou arrasado", "estou com fome", "estou cheio", "estou bravo"], "ans": 0, "exp": "Decepção enorme."}]$j$::jsonb),
('C2', 5011, $$Sinônimos de TIRED$$, $$exhausted$$, $$🔋$$, $$Cansaço tem graus: weary (fatigado), drained (sugado), worn out (esgotado), exhausted (exausto), burnt out (no limite crônico). 'Burnt out' é o cansaço que virou síndrome.$$, $$Very tired ❌ deselegante em C2 → utterly exhausted ✅.$$, $j$[{"en": "I'm absolutely exhausted after the trip.", "pt": "Estou completamente exausto da viagem."}, {"en": "The meeting left me drained.", "pt": "A reunião me deixou sem energia."}, {"en": "She's burnt out from overworking.", "pt": "Ela está esgotada de tanto trabalhar."}]$j$::jsonb, $j$[{"q": "Cansaço extremo pontual:", "ctx": "", "opts": ["exhausted", "sleepy", "lazy", "bored"], "ans": 0, "exp": "Exausto."}, {"q": "Esgotamento crônico do trabalho:", "ctx": "", "opts": ["burnt out", "worn in", "put off", "laid back"], "ans": 0, "exp": "Burnout."}, {"q": "'Drained' sugere:", "ctx": "", "opts": ["energia sugada", "molhado", "com fome", "confuso"], "ans": 0, "exp": "Como bateria drenada."}, {"q": "'Worn out' também descreve:", "ctx": "", "opts": ["roupas gastas", "pessoas ricas", "comida velha", "ideias novas"], "ans": 0, "exp": "Gasto pelo uso — pessoas e objetos."}, {"q": "Par correto com 'exhausted':", "ctx": "", "opts": ["absolutely", "very much", "a bit much", "many"], "ans": 0, "exp": "Adjetivo extremo pede absolutely/utterly."}, {"q": "'Weary' é mais comum em:", "ctx": "", "opts": ["escrita e literatura", "gíria de rua", "textos jurídicos", "receitas"], "ans": 0, "exp": "Tom literário."}]$j$::jsonb),
('C2', 5012, $$Sinônimos de GOOD$$, $$outstanding$$, $$⭐$$, $$Aposente o 'very good': decent (razoável), solid (consistente), remarkable (notável), superb (soberbo), outstanding (excepcional), top-notch (de primeira). Suba a régua do elogio.$$, $$Decent < solid < remarkable < superb/outstanding. 'Decent' é elogio morno!$$, $j$[{"en": "The food was decent, nothing special.", "pt": "A comida era razoável, nada demais."}, {"en": "She delivered an outstanding performance.", "pt": "Ela entregou uma atuação excepcional."}, {"en": "The hotel service was top-notch.", "pt": "O serviço do hotel era de primeira."}]$j$::jsonb, $j$[{"q": "Elogio máximo:", "ctx": "", "opts": ["outstanding", "decent", "okay", "fair"], "ans": 0, "exp": "Excepcional."}, {"q": "'Decent' significa:", "ctx": "", "opts": ["razoável, adequado", "excelente", "péssimo", "caro"], "ans": 0, "exp": "Cumpre o básico."}, {"q": "'Top-notch' =", "ctx": "", "opts": ["de primeira linha", "no topo do prédio", "barulhento", "recente"], "ans": 0, "exp": "Qualidade máxima, informal."}, {"q": "'Remarkable' =", "ctx": "", "opts": ["digno de nota", "remarcável", "comum", "duvidoso"], "ans": 0, "exp": "Notável."}, {"q": "Trabalho consistente e confiável:", "ctx": "", "opts": ["solid", "shaky", "loose", "vague"], "ans": 0, "exp": "Solid work."}, {"q": "'Superb' soa:", "ctx": "", "opts": ["entusiasmado e formal", "irônico sempre", "infantil", "agressivo"], "ans": 0, "exp": "Elogio forte."}]$j$::jsonb),
('C2', 5013, $$Sinônimos de BAD$$, $$dreadful$$, $$🕳️$$, $$Pra baixo também há escala: mediocre (medíocre), lousy (vagabundo), dreadful (horrível), appalling (chocante de ruim), atrocious (atroz). 'Mediocre' fere mais que 'bad' em crítica.$$, $$'Appalling' e 'atrocious' carregam indignação moral — não use para pizza fria.$$, $j$[{"en": "The service was appalling.", "pt": "O atendimento foi vergonhoso."}, {"en": "It was a lousy excuse.", "pt": "Foi uma desculpa esfarrapada."}, {"en": "The weather was dreadful all week.", "pt": "O tempo esteve horrível a semana toda."}]$j$::jsonb, $j$[{"q": "Ruim com indignação:", "ctx": "", "opts": ["appalling", "so-so", "fine", "average"], "ans": 0, "exp": "Revoltante."}, {"q": "'Mediocre' =", "ctx": "", "opts": ["sem brilho, mais ou menos", "excelente", "horroroso", "caro"], "ans": 0, "exp": "A crítica que mais dói."}, {"q": "'Lousy' é:", "ctx": "", "opts": ["informal para vagabundo/ruim", "formal e técnico", "elogio", "neutro"], "ans": 0, "exp": "Informal."}, {"q": "'Dreadful' vem de:", "ctx": "", "opts": ["dread (pavor)", "dream (sonho)", "drama", "bread"], "ans": 0, "exp": "Que causa pavor."}, {"q": "Erro grosseiro e chocante:", "ctx": "", "opts": ["atrocious", "adorable", "average", "adequate"], "ans": 0, "exp": "Atroz."}, {"q": "Qual NÃO combina com comida:", "ctx": "", "opts": ["appalling behavior", "lousy pizza", "dreadful meal", "mediocre dish"], "ans": 0, "exp": "Appalling pede contexto moral/sério."}]$j$::jsonb),
('C2', 5014, $$Verbos de dizer$$, $$mutter$$, $$💬$$, $$Diga adeus ao 'said': whisper (sussurrar), mutter (resmungar), yell (gritar), claim (alegar), admit (admitir). O verbo certo pinta a cena inteira.$$, $$Em fofoca e narrativa, o verbo de dizer é 80% da graça.$$, $j$[{"en": "\"Wait here,\" she whispered.", "pt": "\"Espere aqui\", ela sussurrou."}, {"en": "He muttered something about the boss.", "pt": "Ele resmungou algo sobre o chefe."}, {"en": "She claims she wasn't there.", "pt": "Ela alega que não estava lá."}]$j$::jsonb, $j$[{"q": "Falar baixinho no ouvido:", "ctx": "", "opts": ["whisper", "yell", "declare", "spell"], "ans": 0, "exp": "Sussurrar."}, {"q": "Resmungar entre dentes:", "ctx": "", "opts": ["mutter", "shout", "announce", "hum"], "ans": 0, "exp": "Resmungo."}, {"q": "Gritar com raiva:", "ctx": "", "opts": ["yell", "whisper", "note", "type"], "ans": 0, "exp": "Yell/shout."}, {"q": "Alegar (sem prova):", "ctx": "", "opts": ["claim", "prove", "confirm", "measure"], "ans": 0, "exp": "Claim = diz, mas duvido."}, {"q": "Admitir a contragosto:", "ctx": "", "opts": ["admit", "deny", "refuse", "forbid"], "ans": 0, "exp": "Confessar."}, {"q": "'Ele deixou escapar' =", "ctx": "", "opts": ["he blurted out", "he sealed in", "he backed up", "he called off"], "ans": 0, "exp": "Blurt out = falar sem pensar."}]$j$::jsonb),
('C2', 5015, $$Verbos de andar$$, $$stroll$$, $$🚶$$, $$Cada caminhada tem seu verbo: stroll (passear tranquilo), wander (vagar sem rumo), march (marchar decidido), stagger (cambalear), sneak (andar de fininho).$$, $$"He staggered home" já conta a noite inteira em uma palavra.$$, $j$[{"en": "We strolled along the beach.", "pt": "Passeamos tranquilamente pela praia."}, {"en": "She wandered around the old town.", "pt": "Ela vagou pela cidade velha."}, {"en": "He sneaked out of the meeting.", "pt": "Ele saiu de fininho da reunião."}]$j$::jsonb, $j$[{"q": "Passear sem pressa:", "ctx": "", "opts": ["stroll", "march", "sprint", "stumble"], "ans": 0, "exp": "Caminhada relaxada."}, {"q": "Vagar sem destino:", "ctx": "", "opts": ["wander", "aim", "commute", "park"], "ans": 0, "exp": "Sem rumo."}, {"q": "Andar decidido/bravo:", "ctx": "", "opts": ["march", "tiptoe", "crawl", "drift"], "ans": 0, "exp": "Como militar."}, {"q": "Cambalear (tonto/bêbado):", "ctx": "", "opts": ["stagger", "stride", "slide", "stand"], "ans": 0, "exp": "Sem equilíbrio."}, {"q": "Sair de fininho:", "ctx": "", "opts": ["sneak out", "log out", "work out", "speak out"], "ans": 0, "exp": "Escondido."}, {"q": "Andar na ponta dos pés:", "ctx": "", "opts": ["tiptoe", "stomp", "jog", "dash"], "ans": 0, "exp": "Para não acordar ninguém."}]$j$::jsonb),
('C2', 5016, $$Verbos de olhar$$, $$glance$$, $$👀$$, $$Olhar tem intenção: glance (olhada rápida), stare (encarar), gaze (contemplar), peek (espiar), glare (fuzilar com os olhos).$$, $$Stare é fixo e rude; gaze é fixo e apaixonado. A diferença é o sentimento.$$, $j$[{"en": "She glanced at her watch.", "pt": "Ela deu uma olhada rápida no relógio."}, {"en": "Don't stare at people.", "pt": "Não fique encarando as pessoas."}, {"en": "He gazed at the stars.", "pt": "Ele contemplou as estrelas."}]$j$::jsonb, $j$[{"q": "Olhada rápida:", "ctx": "", "opts": ["glance", "stare", "gaze", "glare"], "ans": 0, "exp": "De relance."}, {"q": "Encarar fixamente (rude):", "ctx": "", "opts": ["stare", "peek", "blink", "wink"], "ans": 0, "exp": "Stare."}, {"q": "Contemplar com admiração:", "ctx": "", "opts": ["gaze", "glare", "squint", "frown"], "ans": 0, "exp": "Gaze."}, {"q": "Espiar escondido:", "ctx": "", "opts": ["peek", "watch", "observe", "notice"], "ans": 0, "exp": "Peek/peep."}, {"q": "Fuzilar com os olhos:", "ctx": "", "opts": ["glare", "gaze", "glimpse", "admire"], "ans": 0, "exp": "Olhar de raiva."}, {"q": "'Catch a glimpse of' =", "ctx": "", "opts": ["ver de relance", "fotografar", "perseguir", "encarar"], "ans": 0, "exp": "Vislumbrar."}]$j$::jsonb),
('C2', 5017, $$Verbos de som$$, $$creak$$, $$🔊$$, $$O inglês ouve tudo: buzz (zumbir), creak (ranger), rattle (chacoalhar), hum (zunir/cantarolar), slam (bater com força). Sons viram verbos direto.$$, $$A porta 'creaks', o celular 'buzzes', a janela 'rattles' — cenário instantâneo.$$, $j$[{"en": "The old door creaked open.", "pt": "A porta velha abriu rangendo."}, {"en": "My phone buzzed twice.", "pt": "Meu celular vibrou duas vezes."}, {"en": "He slammed the door angrily.", "pt": "Ele bateu a porta com raiva."}]$j$::jsonb, $j$[{"q": "Porta velha de madeira:", "ctx": "", "opts": ["creaks", "buzzes", "beeps", "roars"], "ans": 0, "exp": "Range."}, {"q": "Celular no silencioso:", "ctx": "", "opts": ["buzzes", "creaks", "whistles", "claps"], "ans": 0, "exp": "Vibra/zumbe."}, {"q": "Janela solta com vento:", "ctx": "", "opts": ["rattles", "hums", "sighs", "ticks"], "ans": 0, "exp": "Chacoalha."}, {"q": "Cantarolar de boca fechada:", "ctx": "", "opts": ["hum", "yell", "spell", "chant loudly"], "ans": 0, "exp": "Hmmm 🎵."}, {"q": "Bater a porta com força:", "ctx": "", "opts": ["slam", "knock", "tap", "push gently"], "ans": 0, "exp": "Slam!"}, {"q": "Abelhas fazem:", "ctx": "", "opts": ["buzz", "creak", "rattle", "slam"], "ans": 0, "exp": "Zumbido."}]$j$::jsonb),
('C2', 5018, $$Emoções sutis$$, $$bittersweet$$, $$🎭$$, $$Vocabulário emocional fino: bittersweet (agridoce), wistful (nostálgico-saudoso), smug (convencido), overwhelmed (sobrecarregado), relieved (aliviado).$$, $$"Saudade" não tem tradução exata — 'wistful longing' chega perto.$$, $j$[{"en": "Graduation was a bittersweet moment.", "pt": "A formatura foi um momento agridoce."}, {"en": "She gave a wistful smile.", "pt": "Ela deu um sorriso saudoso."}, {"en": "I felt so relieved after the exam.", "pt": "Fiquei muito aliviado depois da prova."}]$j$::jsonb, $j$[{"q": "Alegria misturada com tristeza:", "ctx": "", "opts": ["bittersweet", "sour", "salty", "plain"], "ans": 0, "exp": "Agridoce."}, {"q": "Saudoso, nostálgico:", "ctx": "", "opts": ["wistful", "wasteful", "watchful", "willful"], "ans": 0, "exp": "Wistful."}, {"q": "Convencido, cheio de si:", "ctx": "", "opts": ["smug", "shy", "humble", "gloomy"], "ans": 0, "exp": "Smug."}, {"q": "Sobrecarregado de emoção/tarefas:", "ctx": "", "opts": ["overwhelmed", "underrated", "overrated", "outdated"], "ans": 0, "exp": "Não dou conta!"}, {"q": "Aliviado:", "ctx": "", "opts": ["relieved", "reloaded", "removed", "relayed"], "ans": 0, "exp": "Ufa!"}, {"q": "'Homesick' =", "ctx": "", "opts": ["com saudade de casa", "doente em casa", "sem casa", "caseiro"], "ans": 0, "exp": "Saudade de casa."}]$j$::jsonb),
('C2', 5019, $$Adjetivos extremos$$, $$absolutely freezing$$, $$🌡️$$, $$Adjetivos extremos já contêm o 'muito': freezing (congelante), boiling (fervendo), ancient (antiquíssimo), tiny (minúsculo), furious (furioso). Com eles use absolutely/utterly — nunca very.$$, $$very freezing ❌ | absolutely freezing ✅ | very cold ✅$$, $j$[{"en": "It's absolutely freezing out there!", "pt": "Está congelando lá fora!"}, {"en": "The stadium was absolutely packed.", "pt": "O estádio estava completamente lotado."}, {"en": "She was utterly exhausted.", "pt": "Ela estava totalmente exausta."}]$j$::jsonb, $j$[{"q": "Correto:", "ctx": "", "opts": ["absolutely freezing", "very freezing", "much freezing", "so much freezing"], "ans": 0, "exp": "Extremo pede absolutely."}, {"q": "Extremo de 'angry':", "ctx": "", "opts": ["furious", "annoyed", "upset", "moody"], "ans": 0, "exp": "Furioso."}, {"q": "Extremo de 'hot':", "ctx": "", "opts": ["boiling", "warm", "mild", "heated up"], "ans": 0, "exp": "Fervendo."}, {"q": "Extremo de 'small':", "ctx": "", "opts": ["tiny", "little", "short", "low"], "ans": 0, "exp": "Minúsculo."}, {"q": "Extremo de 'old':", "ctx": "", "opts": ["ancient", "elderly", "aged", "late"], "ans": 0, "exp": "Antiquíssimo."}, {"q": "Com adjetivo normal (cold), use:", "ctx": "", "opts": ["very", "absolutely", "utterly", "totally only"], "ans": 0, "exp": "Very cold; absolutely freezing."}]$j$::jsonb),
('C2', 5020, $$Verbos de mudança$$, $$go bald$$, $$🔄$$, $$Mudança de estado tem verbo certo: go bald/grey/blind (ficar careca/grisalho/cego), turn sour/red (azedar/corar), get worse (piorar), grow old (envelhecer), fall ill (adoecer).$$, $$GO para mudanças ruins (go mad, go wrong), GET para graduais, TURN para cor.$$, $j$[{"en": "He's going bald at 30.", "pt": "Ele está ficando careca aos 30."}, {"en": "The milk turned sour.", "pt": "O leite azedou."}, {"en": "Things got worse after that.", "pt": "As coisas pioraram depois disso."}]$j$::jsonb, $j$[{"q": "Ficar careca:", "ctx": "", "opts": ["go bald", "turn bald", "fall bald", "make bald"], "ans": 0, "exp": "Go bald."}, {"q": "O leite azedou:", "ctx": "", "opts": ["turned sour", "went salty", "got sweet", "fell sour"], "ans": 0, "exp": "Turn + sabor/cor."}, {"q": "Adoecer (formal):", "ctx": "", "opts": ["fall ill", "go ill", "turn ill", "do ill"], "ans": 0, "exp": "Fall ill."}, {"q": "Enlouquecer:", "ctx": "", "opts": ["go mad", "turn mad", "fall mad", "grow mad"], "ans": 0, "exp": "Go mad/crazy."}, {"q": "Corar de vergonha:", "ctx": "", "opts": ["turn red", "go blue", "fall red", "get pink always"], "ans": 0, "exp": "Turn red."}, {"q": "Ficar em silêncio (a sala):", "ctx": "", "opts": ["fell silent", "went noisy", "turned loud", "got talkative"], "ans": 0, "exp": "The room fell silent."}]$j$::jsonb),
('C2', 5021, $$Colocações fortes$$, $$heavy rain$$, $$🧲$$, $$Combinações que soam nativas: heavy rain/traffic (chuva forte/trânsito pesado), strong coffee/accent (café forte/sotaque carregado), high hopes/standards (grandes expectativas/padrões altos). Trocar = soar estrangeiro.$$, $$strong rain ❌ heavy rain ✅ | heavy coffee ❌ strong coffee ✅$$, $j$[{"en": "We got stuck in heavy traffic.", "pt": "Ficamos presos num trânsito pesado."}, {"en": "She has a strong Italian accent.", "pt": "Ela tem um sotaque italiano carregado."}, {"en": "I have high hopes for this project.", "pt": "Tenho grandes expectativas para este projeto."}]$j$::jsonb, $j$[{"q": "Chuva forte:", "ctx": "", "opts": ["heavy rain", "strong rain", "hard rain", "big rain"], "ans": 0, "exp": "Heavy rain."}, {"q": "Café forte:", "ctx": "", "opts": ["strong coffee", "heavy coffee", "hard coffee", "high coffee"], "ans": 0, "exp": "Strong coffee."}, {"q": "Grandes expectativas:", "ctx": "", "opts": ["high hopes", "big hopes", "tall hopes", "heavy hopes"], "ans": 0, "exp": "High hopes."}, {"q": "Fumante inveterado:", "ctx": "", "opts": ["heavy smoker", "strong smoker", "big smoker", "high smoker"], "ans": 0, "exp": "Heavy smoker."}, {"q": "Sotaque carregado:", "ctx": "", "opts": ["strong accent", "heavy voice", "high accent", "hard accent"], "ans": 0, "exp": "Strong accent."}, {"q": "Padrões exigentes:", "ctx": "", "opts": ["high standards", "tall standards", "heavy standards", "strong levels"], "ans": 0, "exp": "High standards."}]$j$::jsonb),
('C2', 5022, $$Colocações formais$$, $$pose a threat$$, $$📎$$, $$Na escrita séria, verbos e substantivos andam em pares: pose a threat (representar ameaça), raise a question (levantar questão), draw a conclusion (tirar conclusão), reach an agreement (chegar a acordo), conduct research (conduzir pesquisa).$$, $$make a research ❌ conduct/do research ✅$$, $j$[{"en": "Pollution poses a serious threat.", "pt": "A poluição representa uma ameaça séria."}, {"en": "The study raises important questions.", "pt": "O estudo levanta questões importantes."}, {"en": "They finally reached an agreement.", "pt": "Finalmente chegaram a um acordo."}]$j$::jsonb, $j$[{"q": "Representar uma ameaça:", "ctx": "", "opts": ["pose a threat", "make a threat only", "do a threat", "put a threat"], "ans": 0, "exp": "Pose a threat."}, {"q": "Tirar uma conclusão:", "ctx": "", "opts": ["draw a conclusion", "take a conclusion", "make a conclude", "pull a conclusion"], "ans": 0, "exp": "Draw."}, {"q": "Chegar a um acordo:", "ctx": "", "opts": ["reach an agreement", "arrive an agreement", "touch an agreement", "get to agree it"], "ans": 0, "exp": "Reach."}, {"q": "Conduzir pesquisa:", "ctx": "", "opts": ["conduct research", "make a research", "drive research", "produce a research"], "ans": 0, "exp": "Conduct/do research."}, {"q": "Levantar uma questão:", "ctx": "", "opts": ["raise a question", "lift a question", "grow a question", "rise a question"], "ans": 0, "exp": "Raise (transitivo)."}, {"q": "Atender à demanda:", "ctx": "", "opts": ["meet the demand", "find the demand", "answer the demand", "reach the demand"], "ans": 0, "exp": "Meet demand/needs."}]$j$::jsonb),
('C2', 5023, $$Compostos modernos$$, $$game-changer$$, $$🚀$$, $$O inglês corporativo adora compostos: game-changer (divisor de águas), deal-breaker (fator eliminatório), must-have (indispensável), know-how (conhecimento prático), breakthrough (avanço revolucionário).$$, $$Deal-breaker: o detalhe que mata o negócio (ou o relacionamento).$$, $j$[{"en": "This app is a real game-changer.", "pt": "Este app é um divisor de águas."}, {"en": "No wifi? That's a deal-breaker.", "pt": "Sem wifi? Isso mata o negócio."}, {"en": "It was a major scientific breakthrough.", "pt": "Foi um grande avanço científico."}]$j$::jsonb, $j$[{"q": "'Game-changer' =", "ctx": "", "opts": ["algo que muda tudo", "jogador novo", "árbitro", "brinquedo"], "ans": 0, "exp": "Divisor de águas."}, {"q": "'Deal-breaker' =", "ctx": "", "opts": ["o que inviabiliza o acordo", "bom negociador", "desconto", "contrato"], "ans": 0, "exp": "Mata o negócio."}, {"q": "'Must-have' =", "ctx": "", "opts": ["item indispensável", "obrigação legal", "dívida", "desejo distante"], "ans": 0, "exp": "Tem que ter."}, {"q": "'Know-how' =", "ctx": "", "opts": ["conhecimento prático", "sabedoria antiga", "diploma", "manual"], "ans": 0, "exp": "Saber fazer."}, {"q": "'Breakthrough' =", "ctx": "", "opts": ["avanço revolucionário", "invasão", "pausa", "quebra de contrato"], "ans": 0, "exp": "Descoberta que destrava."}, {"q": "'A win-win situation' =", "ctx": "", "opts": ["bom para os dois lados", "vitória dupla no jogo", "empate", "sorteio"], "ans": 0, "exp": "Todo mundo ganha."}]$j$::jsonb),
('C2', 5024, $$Sufixos raros$$, $$-esque, -worthy$$, $$🏷️$$, $$Sufixos que refinam: -esque (ao estilo de: picturesque), -ish (meio/aproximado: fortyish), -worthy (digno de: noteworthy), -proof (à prova de: foolproof), -free (livre de: sugar-free).$$, $$"Let's meet at sevenish" = lá pelas sete. O -ish deixa tudo aproximado.$$, $j$[{"en": "The village is really picturesque.", "pt": "O vilarejo é muito pitoresco."}, {"en": "He arrived at eightish.", "pt": "Ele chegou lá pelas oito."}, {"en": "The plan is completely foolproof.", "pt": "O plano é totalmente infalível."}]$j$::jsonb, $j$[{"q": "'Fortyish' =", "ctx": "", "opts": ["uns quarenta e poucos", "exatamente 40", "menos de 30", "muito velho"], "ans": 0, "exp": "-ish = aproximado."}, {"q": "'Noteworthy' =", "ctx": "", "opts": ["digno de nota", "bom de caderno", "musical", "escrito"], "ans": 0, "exp": "-worthy = digno de."}, {"q": "'Foolproof' =", "ctx": "", "opts": ["infalível", "à prova de sábios", "bobo", "frágil"], "ans": 0, "exp": "Nem um leigo erra."}, {"q": "'Waterproof' =", "ctx": "", "opts": ["à prova d'água", "cheio d'água", "sem água", "aquático"], "ans": 0, "exp": "-proof = à prova de."}, {"q": "'Sugar-free' =", "ctx": "", "opts": ["sem açúcar", "açúcar grátis", "doce", "barato"], "ans": 0, "exp": "-free = livre de."}, {"q": "'Kafkaesque' =", "ctx": "", "opts": ["absurdo como em Kafka", "alemão", "literário bom", "antigo"], "ans": 0, "exp": "-esque = ao estilo de."}]$j$::jsonb),
('C2', 5025, $$Prefixos de verbo$$, $$outperform$$, $$📈$$, $$Prefixos multiplicam verbos: outperform (superar), overestimate (superestimar), underestimate (subestimar), misunderstand (entender errado), rewrite (reescrever). Out- = fazer melhor que; over- = demais; under- = de menos; mis- = errado.$$, $$Never underestimate the power of prefixes 😉$$, $j$[{"en": "Our team outperformed the competition.", "pt": "Nosso time superou a concorrência."}, {"en": "I underestimated how hard it would be.", "pt": "Subestimei o quão difícil seria."}, {"en": "She misunderstood my message.", "pt": "Ela entendeu errado minha mensagem."}]$j$::jsonb, $j$[{"q": "Superar (fazer melhor que):", "ctx": "", "opts": ["outperform", "underperform", "misperform", "reperform"], "ans": 0, "exp": "Out- = melhor que."}, {"q": "Cobrar caro demais:", "ctx": "", "opts": ["overcharge", "undercharge", "recharge", "discharge"], "ans": 0, "exp": "Over- = demais."}, {"q": "Subestimar:", "ctx": "", "opts": ["underestimate", "overestimate", "misestimate", "deestimate"], "ans": 0, "exp": "Under- = de menos."}, {"q": "Entender errado:", "ctx": "", "opts": ["misunderstand", "understand again", "outstand", "unstand"], "ans": 0, "exp": "Mis- = errado."}, {"q": "Viver mais que alguém:", "ctx": "", "opts": ["outlive", "overlive", "mislive", "underlive"], "ans": 0, "exp": "Outlive."}, {"q": "Dormir além da hora:", "ctx": "", "opts": ["oversleep", "undersleep", "missleep", "outsleep"], "ans": 0, "exp": "Overslept!"}]$j$::jsonb),
('C2', 5026, $$Falsos anglicismos do Brasil$$, $$outdoor ≠ outdoor$$, $$🇧🇷$$, $$Palavras 'em inglês' que só existem no Brasil: outdoor (billboard), notebook (laptop), chip de celular (SIM card), home office como local (working from home), shopping (mall). Nos EUA, ninguém entende o nosso 'inglês'.$$, $$"I work in home office" ❌ → "I work from home" ✅$$, $j$[{"en": "There's a huge billboard on the highway.", "pt": "Tem um outdoor enorme na rodovia."}, {"en": "I bought a new SIM card for my phone.", "pt": "Comprei um chip novo para o celular."}, {"en": "Let's meet at the mall.", "pt": "Vamos nos encontrar no shopping."}]$j$::jsonb, $j$[{"q": "Outdoor (de rua) em inglês:", "ctx": "", "opts": ["billboard", "outdoor", "outside", "poster wall"], "ans": 0, "exp": "Billboard."}, {"q": "Notebook (computador):", "ctx": "", "opts": ["laptop", "notebook only", "copybook", "netbook"], "ans": 0, "exp": "Laptop (notebook = caderno)."}, {"q": "Chip de celular:", "ctx": "", "opts": ["SIM card", "chip", "cell chip", "phone card"], "ans": 0, "exp": "SIM card."}, {"q": "Trabalhar de casa:", "ctx": "", "opts": ["work from home", "work in home office", "make home office", "stay in office"], "ans": 0, "exp": "Work from home / remotely."}, {"q": "Shopping (o lugar):", "ctx": "", "opts": ["mall", "shopping", "shop center", "buying center"], "ans": 0, "exp": "Mall / shopping mall."}, {"q": "Smoking (roupa):", "ctx": "", "opts": ["tuxedo", "smoking", "smoke suit", "night suit"], "ans": 0, "exp": "Tuxedo/tux."}]$j$::jsonb),
('C2', 5027, $$Empréstimos do francês$$, $$déjà vu$$, $$🥐$$, $$O inglês chique fala francês: déjà vu (sensação de já vivido), faux pas (gafe), cliché (clichê), fiancé/fiancée (noivo/a), résumé (currículo, AmE). Pronúncia afrancesada e tudo.$$, $$Résumé (currículo) ≠ resume (retomar). O acento muda a palavra!$$, $j$[{"en": "I had a strange sense of déjà vu.", "pt": "Tive uma estranha sensação de déjà vu."}, {"en": "Asking her age was a real faux pas.", "pt": "Perguntar a idade dela foi uma baita gafe."}, {"en": "Send your résumé by Friday.", "pt": "Envie seu currículo até sexta."}]$j$::jsonb, $j$[{"q": "Gafe social:", "ctx": "", "opts": ["faux pas", "faux gras", "déjà vu", "en route"], "ans": 0, "exp": "Passo em falso."}, {"q": "Currículo (AmE):", "ctx": "", "opts": ["résumé", "resume (verbo)", "curriculum only", "biography"], "ans": 0, "exp": "Résumé (ou CV)."}, {"q": "Noiva:", "ctx": "", "opts": ["fiancée", "fiancé", "financier", "fondue"], "ans": 0, "exp": "Fiancée (com -ée)."}, {"q": "'Cliché' =", "ctx": "", "opts": ["ideia batida", "foto", "francês nato", "elogio"], "ans": 0, "exp": "Clichê."}, {"q": "'RSVP' num convite pede:", "ctx": "", "opts": ["confirmação de presença", "traje formal", "presente", "pontualidade"], "ans": 0, "exp": "Répondez s'il vous plaît."}, {"q": "'Entrepreneur' =", "ctx": "", "opts": ["empreendedor", "entregador", "artista", "chef"], "ans": 0, "exp": "Do francês, uso universal."}]$j$::jsonb),
('C2', 5028, $$Tônica que muda o sentido$$, $$REcord × reCORD$$, $$🎚️$$, $$Mesma escrita, tônicas diferentes: REcord (substantivo: disco/registro) × reCORD (verbo: gravar); PREsent (presente) × preSENT (apresentar); OBject (objeto) × obJECT (objetar); PERmit (licença) × perMIT (permitir).$$, $$Regra de ouro: substantivo = tônica no começo; verbo = tônica no fim.$$, $j$[{"en": "She broke the world REcord.", "pt": "Ela quebrou o recorde mundial."}, {"en": "We need to reCORD the meeting.", "pt": "Precisamos gravar a reunião."}, {"en": "They will preSENT the results today.", "pt": "Eles vão apresentar os resultados hoje."}]$j$::jsonb, $j$[{"q": "Gravar um podcast: tônica em", "ctx": "", "opts": ["reCORD (fim)", "REcord (início)", "tanto faz", "nenhuma"], "ans": 0, "exp": "Verbo = fim."}, {"q": "O disco/recorde: tônica em", "ctx": "", "opts": ["REcord (início)", "reCORD (fim)", "tanto faz", "depende da região"], "ans": 0, "exp": "Substantivo = início."}, {"q": "'Apresentar' =", "ctx": "", "opts": ["preSENT", "PREsent", "PRESent", "presENTE"], "ans": 0, "exp": "Verbo, tônica no fim."}, {"q": "'Objeto' =", "ctx": "", "opts": ["OBject", "obJECT", "objECT", "oBJect"], "ans": 0, "exp": "Substantivo, início."}, {"q": "'Licença/alvará' =", "ctx": "", "opts": ["PERmit", "perMIT", "PErmit", "permIT"], "ans": 0, "exp": "Substantivo, início."}, {"q": "A regra geral:", "ctx": "", "opts": ["substantivo início, verbo fim", "verbo início, substantivo fim", "sempre no fim", "sempre no início"], "ans": 0, "exp": "NOUN-first, verb-last."}]$j$::jsonb),
('C2', 5029, $$Letras mudas traiçoeiras$$, $$colonel = kernel$$, $$🤫$$, $$O inglês esconde letras: colonel (soa 'kernel'), subtle (o b é mudo), receipt (o p é mudo), island (o s é mudo), debt (o b é mudo). Ler como se escreve = entregar o jogo.$$, $$Colonel soa exatamente como kernel. Sim, é bizarro. Sim, é assim mesmo.$$, $j$[{"en": "The colonel gave the order.", "pt": "O coronel deu a ordem."}, {"en": "There's a subtle difference.", "pt": "Há uma diferença sutil."}, {"en": "Keep the receipt, please.", "pt": "Guarde o recibo, por favor."}]$j$::jsonb, $j$[{"q": "'Colonel' soa como:", "ctx": "", "opts": ["kernel", "colonial", "co-lo-nel", "colon"], "ans": 0, "exp": "Total pegadinha."}, {"q": "Letra muda em 'subtle':", "ctx": "", "opts": ["b", "t", "s", "l"], "ans": 0, "exp": "SUH-tl."}, {"q": "Letra muda em 'receipt':", "ctx": "", "opts": ["p", "c", "e", "t"], "ans": 0, "exp": "ri-SEET."}, {"q": "Letra muda em 'island':", "ctx": "", "opts": ["s", "l", "d", "i"], "ans": 0, "exp": "EYE-land."}, {"q": "Letra muda em 'debt':", "ctx": "", "opts": ["b", "d", "t", "e"], "ans": 0, "exp": "DET."}, {"q": "Em 'Wednesday' não se ouve:", "ctx": "", "opts": ["o primeiro d", "o w", "o y", "o s"], "ans": 0, "exp": "WENZ-day."}]$j$::jsonb),
('C2', 5030, $$Plurais que mudam o sentido$$, $$customs$$, $$👓$$, $$No plural, outra palavra: custom (costume) → customs (alfândega); content (conteúdo) → contents (índice/o que está dentro); good (bom) → goods (mercadorias); manner (maneira) → manners (educação); glass (vidro) → glasses (óculos).$$, $$"Where are my glasses?" nunca é sobre copos... contexto!$$, $j$[{"en": "We went through customs quickly.", "pt": "Passamos rápido pela alfândega."}, {"en": "Check the table of contents.", "pt": "Confira o índice."}, {"en": "Mind your manners!", "pt": "Modos! / Comporte-se!"}]$j$::jsonb, $j$[{"q": "'Customs' (no aeroporto) =", "ctx": "", "opts": ["alfândega", "costumes", "clientes", "roupas"], "ans": 0, "exp": "Customs = alfândega."}, {"q": "'Goods' =", "ctx": "", "opts": ["mercadorias", "coisas boas", "notas altas", "vantagens"], "ans": 0, "exp": "Bens/produtos."}, {"q": "'Manners' =", "ctx": "", "opts": ["educação, modos", "maneiras de fazer", "manias", "homens"], "ans": 0, "exp": "Good manners!"}, {"q": "'Contents' =", "ctx": "", "opts": ["o que está dentro/índice", "contentamentos", "concorrentes", "continentes"], "ans": 0, "exp": "Table of contents."}, {"q": "'Glasses' =", "ctx": "", "opts": ["óculos", "copos sempre", "vidros da janela", "taças"], "ans": 0, "exp": "Quase sempre óculos."}, {"q": "'Arms' também significa:", "ctx": "", "opts": ["armas", "pernas", "mangas", "abraços"], "ans": 0, "exp": "Braços E armas."}]$j$::jsonb),
('C2', 5031, $$Coletivos curiosos$$, $$a pride of lions$$, $$🦁$$, $$Coletivos que impressionam: a flock of birds (bando de pássaros), a school of fish (cardume), a pride of lions (alcateia de leões), a swarm of bees (enxame), a pack of wolves (matilha).$$, $$'School of fish' não é escola — é cardume! Um clássico das pegadinhas.$$, $j$[{"en": "A flock of birds flew south.", "pt": "Um bando de pássaros voou para o sul."}, {"en": "We saw a school of dolphins.", "pt": "Vimos um cardume de golfinhos."}, {"en": "A swarm of bees crossed the garden.", "pt": "Um enxame de abelhas cruzou o jardim."}]$j$::jsonb, $j$[{"q": "Cardume:", "ctx": "", "opts": ["a school of fish", "a class of fish", "a team of fish", "a group of fishes"], "ans": 0, "exp": "School!"}, {"q": "Grupo de leões:", "ctx": "", "opts": ["a pride of lions", "a crowd of lions", "a gang of lions", "a herd of lions"], "ans": 0, "exp": "Pride."}, {"q": "Enxame de abelhas:", "ctx": "", "opts": ["a swarm of bees", "a storm of bees", "a cloud of bees", "a box of bees"], "ans": 0, "exp": "Swarm."}, {"q": "Matilha de lobos:", "ctx": "", "opts": ["a pack of wolves", "a pile of wolves", "a squad of wolves", "a set of wolves"], "ans": 0, "exp": "Pack."}, {"q": "Bando de pássaros:", "ctx": "", "opts": ["a flock of birds", "a block of birds", "a fleet of birds", "a band of birds"], "ans": 0, "exp": "Flock."}, {"q": "Rebanho de vacas:", "ctx": "", "opts": ["a herd of cows", "a heap of cows", "a horde of cows", "a hive of cows"], "ans": 0, "exp": "Herd."}]$j$::jsonb),
('C2', 5032, $$Relativos formais$$, $$whom & whereby$$, $$📜$$, $$A escrita culta usa relativos precisos: whom (quem, como objeto), whose (cujo), whereby (pelo qual), wherein (no qual), of which (do qual). Marca registrada de contrato, paper e e-mail sério.$$, $$Regra prática do whom: se responderia com HIM/HER, use whom.$$, $j$[{"en": "The client to whom I spoke agreed.", "pt": "O cliente com quem falei concordou."}, {"en": "A system whereby users earn points.", "pt": "Um sistema pelo qual usuários ganham pontos."}, {"en": "The author whose book won the prize.", "pt": "O autor cujo livro ganhou o prêmio."}]$j$::jsonb, $j$[{"q": "'To ___ it may concern':", "ctx": "", "opts": ["whom", "who", "whose", "which"], "ans": 0, "exp": "A quem possa interessar."}, {"q": "'Cujo' =", "ctx": "", "opts": ["whose", "whom", "which", "whereby"], "ans": 0, "exp": "Posse."}, {"q": "'Pelo qual (mecanismo)' =", "ctx": "", "opts": ["whereby", "wherein", "whereas", "wherever"], "ans": 0, "exp": "A system whereby..."}, {"q": "Use WHOM quando:", "ctx": "", "opts": ["é objeto (him/her)", "é sujeito", "é lugar", "é tempo"], "ans": 0, "exp": "Preposição + whom."}, {"q": "'Wherein' =", "ctx": "", "opts": ["no qual", "para onde", "enquanto", "portanto"], "ans": 0, "exp": "Formal: in which."}, {"q": "'Most of ___ were new':", "ctx": "", "opts": ["whom", "who", "whose", "where"], "ans": 0, "exp": "Most of whom (pessoas)."}]$j$::jsonb),
('C2', 5033, $$Advérbios de postura$$, $$arguably$$, $$🎙️$$, $$Advérbios que posicionam o falante: arguably (indiscutivelmente discutível 😉), admittedly (é verdade que), frankly (francamente), presumably (presumivelmente), ultimately (no fim das contas).$$, $$"Arguably the best" = dá para argumentar que é o melhor — opinião com escudo.$$, $j$[{"en": "He's arguably the best player ever.", "pt": "Ele é possivelmente o melhor jogador de todos."}, {"en": "Admittedly, I was wrong about her.", "pt": "Confesso que eu estava errado sobre ela."}, {"en": "Frankly, I don't care anymore.", "pt": "Francamente, já não me importo."}]$j$::jsonb, $j$[{"q": "Opinião defensável:", "ctx": "", "opts": ["arguably", "angrily", "utterly", "barely"], "ans": 0, "exp": "Dá para argumentar."}, {"q": "Admitindo um ponto contra si:", "ctx": "", "opts": ["admittedly", "proudly", "secretly", "loudly"], "ans": 0, "exp": "Confesso que..."}, {"q": "Sem rodeios:", "ctx": "", "opts": ["frankly", "vaguely", "politely", "quietly"], "ans": 0, "exp": "Francamente."}, {"q": "Supondo pelo contexto:", "ctx": "", "opts": ["presumably", "precisely", "surely 100%", "randomly"], "ans": 0, "exp": "Presume-se."}, {"q": "No fim das contas:", "ctx": "", "opts": ["ultimately", "immediately", "initially", "temporarily"], "ans": 0, "exp": "Em última análise."}, {"q": "'Ironically' introduz:", "ctx": "", "opts": ["um contraste irônico", "uma ordem", "um pedido", "um número"], "ans": 0, "exp": "Ironia do destino."}]$j$::jsonb),
('C2', 5034, $$Only, even, just: posição$$, $$only mexe com tudo$$, $$🎯$$, $$A posição muda o sentido: Only I love you (só eu te amo) ≠ I only love you (eu só te amo, nada mais) ≠ I love only you (amo só você). O advérbio gruda no que modifica.$$, $$Coloque only imediatamente antes da palavra que ele limita.$$, $j$[{"en": "Only she passed the test.", "pt": "Só ela passou na prova (mais ninguém)."}, {"en": "She only read the summary.", "pt": "Ela apenas leu o resumo (não estudou)."}, {"en": "She read only the summary.", "pt": "Ela leu só o resumo (nada mais)."}]$j$::jsonb, $j$[{"q": "'I love only you' =", "ctx": "", "opts": ["amo só você", "só eu amo", "amo até você", "mal te amo"], "ans": 0, "exp": "Only limita 'you'."}, {"q": "'Only I can do it' =", "ctx": "", "opts": ["só eu posso fazer", "posso fazer sozinho", "só posso fazer isso", "faço às vezes"], "ans": 0, "exp": "Only limita 'I'."}, {"q": "'Even John came' =", "ctx": "", "opts": ["até o John veio", "o John veio igual", "só o John veio", "nem o John veio"], "ans": 0, "exp": "Even = até (surpresa)."}, {"q": "'He didn't even call' =", "ctx": "", "opts": ["ele nem ligou", "ele ligou igual", "ele só ligou", "ele quase ligou"], "ans": 0, "exp": "Nem sequer."}, {"q": "'Just arrived' =", "ctx": "", "opts": ["acabou de chegar", "chegou com justiça", "só chegou", "chegou tarde"], "ans": 0, "exp": "Just = acabou de."}, {"q": "'I just want to talk' =", "ctx": "", "opts": ["eu só quero conversar", "acabei de conversar", "converso com justiça", "quero muito"], "ans": 0, "exp": "Just = apenas."}]$j$::jsonb),
('C2', 5035, $$Concordância traiçoeira$$, $$none of us is/are?$$, $$🧮$$, $$Casos que derrubam até nativos: a number of people ARE (vários) × the number of people IS (o número); none of us is/are (ambos aceitos); either of them IS; everyone IS; the police ARE.$$, $$POLICE é sempre plural: The police are coming. FAMILY pode ser os dois (BrE).$$, $j$[{"en": "A number of students are missing.", "pt": "Vários alunos estão faltando."}, {"en": "The number of students is growing.", "pt": "O número de alunos está crescendo."}, {"en": "The police are investigating the case.", "pt": "A polícia está investigando o caso."}]$j$::jsonb, $j$[{"q": "'The police ___ here':", "ctx": "", "opts": ["are", "is", "be", "was"], "ans": 0, "exp": "Police = plural."}, {"q": "'A number of issues ___ found':", "ctx": "", "opts": ["were", "was", "is", "has"], "ans": 0, "exp": "A number of = vários → plural."}, {"q": "'The number of cars ___ increasing':", "ctx": "", "opts": ["is", "are", "were", "have"], "ans": 0, "exp": "O número = singular."}, {"q": "'Everyone ___ invited':", "ctx": "", "opts": ["is", "are", "were", "be"], "ans": 0, "exp": "Everyone = singular."}, {"q": "'Either of the plans ___ fine':", "ctx": "", "opts": ["is", "are", "am", "be plural"], "ans": 0, "exp": "Either = singular (formal)."}, {"q": "'My family ___ big' (AmE):", "ctx": "", "opts": ["is", "are", "been", "may plural"], "ans": 0, "exp": "AmE trata como singular."}]$j$::jsonb),
('C2', 5036, $$Concessão avançada$$, $$no matter what$$, $$🛡️$$, $$Concessão de alto nível: no matter what/how/where (não importa o quê/como/onde), whatever happens (aconteça o que acontecer), however hard it is (por mais difícil que seja), even so (mesmo assim), albeit (embora — formal).$$, $$Albeit = although, mas só para encaixes curtos: 'a small, albeit important, detail'.$$, $j$[{"en": "No matter what happens, I'll be there.", "pt": "Não importa o que aconteça, estarei lá."}, {"en": "However hard he tried, he failed.", "pt": "Por mais que tentasse, ele falhava."}, {"en": "It was a good result, albeit expensive.", "pt": "Foi um bom resultado, embora caro."}]$j$::jsonb, $j$[{"q": "'Aconteça o que acontecer':", "ctx": "", "opts": ["whatever happens", "whatever happened yesterday", "so what happens", "what happens if"], "ans": 0, "exp": "Whatever happens."}, {"q": "'Por mais difícil que seja':", "ctx": "", "opts": ["however hard it is", "how hard is it", "so hard it is", "very hard although"], "ans": 0, "exp": "However + adjetivo."}, {"q": "'Albeit' =", "ctx": "", "opts": ["embora (formal, curto)", "além disso", "portanto", "no entanto longo"], "ans": 0, "exp": "= though, em encaixes."}, {"q": "'No matter how...' =", "ctx": "", "opts": ["não importa quão...", "sem matéria", "de qualquer jeito ruim", "como sempre"], "ans": 0, "exp": "No matter how expensive..."}, {"q": "'Even so' =", "ctx": "", "opts": ["mesmo assim", "até isso", "tão igual", "por isso"], "ans": 0, "exp": "Apesar disso."}, {"q": "'Regardless of the cost' =", "ctx": "", "opts": ["independentemente do custo", "sem olhar o troco", "por causa do custo", "com desconto"], "ans": 0, "exp": "Não importa o custo."}]$j$::jsonb),
('C2', 5037, $$The + adjetivo$$, $$the rich, the brave$$, $$👥$$, $$The + adjetivo vira grupo de pessoas: the rich (os ricos), the poor (os pobres), the unemployed (os desempregados), the elderly (os idosos), the French (os franceses). Sem acrescentar 'people'.$$, $$É sempre plural: The rich ARE getting richer (sem 's' no adjetivo!).$$, $j$[{"en": "The rich are getting richer.", "pt": "Os ricos estão ficando mais ricos."}, {"en": "We should protect the elderly.", "pt": "Devemos proteger os idosos."}, {"en": "The French love their cuisine.", "pt": "Os franceses amam sua culinária."}]$j$::jsonb, $j$[{"q": "'Os desempregados' =", "ctx": "", "opts": ["the unemployed", "the unemployeds", "unemployed people only", "the unemployment"], "ans": 0, "exp": "The + adj, sem s."}, {"q": "'The elderly' =", "ctx": "", "opts": ["os idosos", "a idade", "os antigos objetos", "os mais velhos irmãos"], "ans": 0, "exp": "Idosos, com respeito."}, {"q": "'The rich ___ powerful':", "ctx": "", "opts": ["are", "is", "be", "was"], "ans": 0, "exp": "Plural sempre."}, {"q": "'Os impossíveis' (abstrato): 'expect ___'", "ctx": "", "opts": ["the impossible", "the impossibles", "impossibles", "an impossible"], "ans": 0, "exp": "Abstrato também: the unknown."}, {"q": "'Os franceses' =", "ctx": "", "opts": ["the French", "the Frenchs", "the Frenchies", "Frenches"], "ans": 0, "exp": "Nacionalidades em -ch/-sh."}, {"q": "'The homeless need help' fala de:", "ctx": "", "opts": ["pessoas sem-teto", "uma casa vazia", "os sem rumo", "imóveis"], "ans": 0, "exp": "Grupo social."}]$j$::jsonb),
('C2', 5038, $$Probabilidade nuançada$$, $$bound to happen$$, $$🎲$$, $$Entre o sim e o não: bound to (certeza — vai acontecer), liable to (propenso a — geralmente negativo), the odds are (as chances são), there's a fair chance (boa chance), at best/at worst (na melhor/pior das hipóteses).$$, $$'It's bound to rain' = pode apostar que chove.$$, $j$[{"en": "He's bound to notice the mistake.", "pt": "Ele com certeza vai notar o erro."}, {"en": "The odds are we'll win the case.", "pt": "As chances são de ganharmos o caso."}, {"en": "At worst, we lose one day.", "pt": "Na pior das hipóteses, perdemos um dia."}]$j$::jsonb, $j$[{"q": "'Bound to' indica:", "ctx": "", "opts": ["quase certeza", "proibição", "dúvida total", "medo"], "ans": 0, "exp": "Vai acontecer."}, {"q": "'Liable to' costuma indicar:", "ctx": "", "opts": ["tendência a algo ruim", "desejo", "obrigação legal só", "sorte"], "ans": 0, "exp": "Propenso (negativo)."}, {"q": "'The odds are...' =", "ctx": "", "opts": ["as chances são de...", "os números ímpares", "as dívidas são", "os azares"], "ans": 0, "exp": "Probabilidade."}, {"q": "'At best' =", "ctx": "", "opts": ["na melhor das hipóteses", "no máximo esforço", "melhor que todos", "enfim"], "ans": 0, "exp": "Cenário otimista."}, {"q": "'A fair chance' =", "ctx": "", "opts": ["uma boa chance", "uma chance justa no tribunal", "meia chance", "chance rara"], "ans": 0, "exp": "Provável."}, {"q": "'It's a long shot' =", "ctx": "", "opts": ["é um tiro no escuro", "é um tiro longo", "é certeza", "é perto"], "ans": 0, "exp": "Improvável, mas tentamos."}]$j$::jsonb),
('C2', 5039, $$Linguagem de debate$$, $$play devil's advocate$$, $$⚖️$$, $$Debata como gente grande: concede a point (reconhecer um ponto), rebut (rebater), counterargument (contra-argumento), valid point (ponto válido), play devil's advocate (fazer o advogado do diabo).$$, $$Conceder um ponto fortalece você: 'Fair point, however...'$$, $j$[{"en": "That's a valid point, I must concede.", "pt": "É um ponto válido, devo reconhecer."}, {"en": "Let me play devil's advocate here.", "pt": "Deixa eu fazer o advogado do diabo aqui."}, {"en": "She rebutted every argument.", "pt": "Ela rebateu todos os argumentos."}]$j$::jsonb, $j$[{"q": "Reconhecer um ponto do rival:", "ctx": "", "opts": ["concede", "deny", "ignore", "steal"], "ans": 0, "exp": "Conceder."}, {"q": "Rebater com argumentos:", "ctx": "", "opts": ["rebut", "rebuild", "rebound", "regret"], "ans": 0, "exp": "Refutar."}, {"q": "'Play devil's advocate' =", "ctx": "", "opts": ["defender o lado oposto de propósito", "ser advogado ruim", "trapacear", "desistir"], "ans": 0, "exp": "Testar o argumento."}, {"q": "'Straw man' é:", "ctx": "", "opts": ["distorcer o argumento do outro", "homem fraco", "espantalho de fazenda", "elogio"], "ans": 0, "exp": "Falácia do espantalho."}, {"q": "'Fair point' =", "ctx": "", "opts": ["ponto justo/válido", "ponto de feira", "meio ponto", "opinião fraca"], "ans": 0, "exp": "Você tem razão nisso."}, {"q": "'I beg to differ' =", "ctx": "", "opts": ["discordo respeitosamente", "imploro por diferença", "peço desculpas", "concordo"], "ans": 0, "exp": "Discordância educada."}]$j$::jsonb),
('C2', 5040, $$Inglês jurídico do dia a dia$$, $$terms and conditions$$, $$🧑‍⚖️$$, $$O juridiquês que você já aceita sem ler: terms and conditions (termos e condições), hereby (por meio deste), notwithstanding (não obstante), null and void (sem efeito), breach (violação de contrato).$$, $$"I hereby declare..." — o hereby dá o tom solene de documento.$$, $j$[{"en": "I hereby confirm my resignation.", "pt": "Por meio desta, confirmo minha demissão."}, {"en": "The contract is null and void.", "pt": "O contrato está sem efeito."}, {"en": "They sued him for breach of contract.", "pt": "Processaram-no por quebra de contrato."}]$j$::jsonb, $j$[{"q": "'Hereby' =", "ctx": "", "opts": ["por meio deste", "aqui perto", "até aqui", "de agora em diante"], "ans": 0, "exp": "Formalíssimo."}, {"q": "'Null and void' =", "ctx": "", "opts": ["sem validade", "vazio e nulo de emoção", "zero a zero", "confidencial"], "ans": 0, "exp": "Sem efeito legal."}, {"q": "'Breach of contract' =", "ctx": "", "opts": ["quebra de contrato", "praia do contrato", "assinatura", "renovação"], "ans": 0, "exp": "Violação."}, {"q": "'Notwithstanding' =", "ctx": "", "opts": ["não obstante", "sem ficar de pé", "sem perceber", "notavelmente"], "ans": 0, "exp": "= despite."}, {"q": "'Terms and conditions' =", "ctx": "", "opts": ["termos e condições", "prazos e climas", "aulas e regras", "leis penais"], "ans": 0, "exp": "O que ninguém lê."}, {"q": "'Liability' =", "ctx": "", "opts": ["responsabilidade legal", "liberdade", "aliança", "habilidade"], "ans": 0, "exp": "Responsabilidade jurídica."}]$j$::jsonb);